try:
    expression
except NameError:
    expression = None
try:
    variable
except NameError:
    variable = None
try:
    point
except NameError:
    point = None
try:
    direction
except NameError:
    direction = None

if not isinstance(expression, str):
    raise ValueError('expression must be a string')
if not isinstance(variable, str):
    raise ValueError('variable must be a string')
if not isinstance(point, str):
    raise ValueError('point must be a string')
if direction is None:
    direction = '+'
elif not isinstance(direction, str):
    raise ValueError("direction must be '+', '-', or '+-'")
else:
    direction = direction.strip()
if direction not in ('+', '-', '+-'):
    raise ValueError("direction must be '+', '-', or '+-'")

try:
    expr = sympy.sympify(expression)
    var = sympy.sympify(variable)
    pt = sympy.sympify(point)
except Exception as exc:
    raise ValueError(f'could not parse expression, variable, or point: {exc}')

try:
    result_obj = sympy.limit(expr, var, pt, dir=direction)
except Exception as exc:
    raise ValueError(f'limit evaluation failed: {exc}')

return {
    'expression': expression,
    'variable': variable,
    'point': point,
    'direction': direction,
    'result': str(result_obj),
}

try:
    expression
except NameError:
    expression = None
try:
    operation
except NameError:
    operation = None
try:
    deep
except NameError:
    deep = None
try:
    ratio
except NameError:
    ratio = None

if operation is None:
    operation = 'simplify'
elif not isinstance(operation, str):
    raise ValueError('operation must be a string')
else:
    operation = operation.strip()
if operation not in ('simplify', 'factor'):
    raise ValueError("operation must be 'simplify' or 'factor'")
if not isinstance(expression, str):
    raise ValueError('expression must be a string')
if deep is None:
    deep = False
if not isinstance(deep, bool):
    raise ValueError('deep must be a boolean')
if ratio is None:
    ratio = 1.7
if isinstance(ratio, bool) or not isinstance(ratio, (int, float)):
    raise ValueError('ratio must be a number')

try:
    expr = sympy.sympify(expression)
except Exception as exc:
    raise ValueError(f'could not parse expression: {exc}')

try:
    if operation == 'factor':
        result_obj = sympy.factor(expr, deep=deep)
    else:
        result_obj = sympy.simplify(expr, ratio=ratio)
except Exception as exc:
    raise ValueError(f'{operation} failed: {exc}')

return {
    'operation': operation,
    'expression': expression,
    'result': str(result_obj),
}
